terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Configuration options such as project or region can be set here or via environment variables
}

resource "google_storage_bucket" "bucket" {
  name                        = "my-app-storage-bucket-example"
  location                    = "US"
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  lifecycle_rule {
    condition {
      age = 30
    }
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }
  }

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Project and region can be supplied via environment variables or provider attributes
}

resource "google_storage_bucket" "secure_bucket" {
  name     = "example-secure-bucket"
  location = "US"

  # Enforce uniform bucket-level access as required by organization policy
  uniform_bucket_level_access = true

  # Enforce public access prevention to prevent public exposure
  public_access_prevention = "enforced"

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {}

# Cloud Storage bucket for invoice archives with object versioning enabled
resource "google_storage_bucket" "invoices_archive" {
  name                        = "acme-invoices-archive"
  location                    = "asia-south1"
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  versioning {
    enabled = true
  }

  labels = {
    purpose    = "invoices-archive"
    managed_by = "terraform"
  }
}

# Terraform configuration for a private Cloud Storage bucket and a service account
# with read-only object access (roles/storage.objectViewer).

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {}

variable "project_id" {
  type        = string
  description = "The GCP project ID where resources will be created."
}

variable "bucket_name" {
  type        = string
  description = "The globally unique name for the private Cloud Storage bucket."
}

variable "location" {
  type        = string
  description = "The GCS bucket location."
  default     = "US"
}

# Service account for reading bucket objects
resource "google_service_account" "bucket_reader" {
  project      = var.project_id
  account_id   = "gcs-object-reader"
  display_name = "GCS Object Reader"
  description  = "Service account granted read-only access to Cloud Storage bucket objects."
}

# Private Cloud Storage bucket
resource "google_storage_bucket" "private_bucket" {
  project                     = var.project_id
  name                        = var.bucket_name
  location                    = var.location
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

# IAM member granting read-only object access to the service account
resource "google_storage_bucket_iam_member" "object_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.bucket_reader.email}"
}

# Terraform configuration for a Cloud Storage bucket in europe-west1 with COLDLINE storage class

