resource "google_sql_database_instance" "ha_mysql_instance" {
  name                = "mysql-8-regional-instance"
  database_version    = "MYSQL_8_0"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      # Secure default: disable public IPv4 access
      ipv4_enabled = false
    }
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Configuration options such as project and region can be provided via environment variables or set here.
}

# VPC network for private Cloud SQL connectivity
resource "google_compute_network" "private_network" {
  name                    = "sql-vpc-network"
  auto_create_subnetworks = false
}

# Subnet for general workloads
resource "google_compute_subnetwork" "private_subnet" {
  name          = "sql-vpc-subnet"
  ip_cidr_range = "10.0.0.0/24"
  region        = "us-central1"
  network       = google_compute_network.private_network.id
}

# Reserve an internal IP address range for Google private services access
resource "google_compute_global_address" "private_ip_alloc" {
  name          = "private-ip-alloc"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.private_network.id
}

# Establish private VPC peering for Cloud SQL
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.private_network.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_alloc.name]
}

# Cloud SQL PostgreSQL instance with no public IP and deletion protection enabled
resource "google_sql_database_instance" "postgres_instance" {
  name                = "postgres-instance-primary"
  database_version    = "POSTGRES_15"
  region              = "us-central1"
  deletion_protection = true

  depends_on = [google_service_networking_connection.private_vpc_connection]

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.private_network.id
    }

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    user_labels = {
      environment = "production"
    }
  }
}

