    # Enforce secure defaults by disabling public IPv4 access
    ip_configuration {
      ipv4_enabled = false
    }

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }
  }
}

# Terraform configuration for a Google Cloud Storage bucket with a 90-day object deletion lifecycle policy.

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Configuration options such as project and region can be provided here or via environment variables
}

resource "google_storage_bucket" "auto_delete_bucket" {
  name     = "app-data-90d-retention-bucket"
  location = "US"

  # Enforce uniform bucket-level access for security and IAM-only control
  uniform_bucket_level_access = true

  # Lifecycle rule to delete objects 90 days after creation
  lifecycle_rule {
    condition {
      age = 90
    }
    action {
      type = "Delete"
    }
  }

  labels = {
    environment = "production"
    managed_by  = "terraform"
    purpose     = "ephemeral-storage"
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Default project and region can be supplied via environment variables
  # (e.g., GOOGLE_PROJECT, GOOGLE_REGION) or configured here.
}

# Cloud SQL PostgreSQL instance with point-in-time recovery (PITR) enabled
resource "google_sql_database_instance" "default" {
  name                = "postgres-pitr-instance"
  database_version    = "POSTGRES_15"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
      start_time                     = "03:00"
      transaction_log_retention_days = 7
    }

    ip_configuration {
      # Disables public IP address to adhere to secure defaults
      ipv4_enabled = false
    }
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

data "google_project" "current" {}

# Dedicated service account for GKE node pool
resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Pool Service Account"
}

# Regional GKE Cluster in asia-south1
resource "google_container_cluster" "primary" {
  name     = "primary-cluster"
  location = "asia-south1"

  # Remove default node pool immediately and use a separately managed node pool
  remove_default_node_pool = true
  initial_node_count       = 1

  # Network and security best practices
  private_cluster_config {
    enable_private_nodes = true
  }

  workload_identity_config {
    workload_pool = "${data.google_project.current.project_id}.svc.id.goog"
  }

  release_channel {
    channel = "REGULAR"
  }

  resource_labels = {
    environment = "prod"
  }
}

# Separately managed node pool with 3 e2-standard-4 nodes
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  location   = "asia-south1"
  cluster    = google_container_cluster.primary.name
  node_count = 3

  node_config {
    machine_type    = "e2-standard-4"
    service_account = google_service_account.gke_nodes.email

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = {
      environment = "prod"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Dedicated VPC network for the GKE cluster to adhere to secure networking practices
resource "google_compute_network" "gke_vpc" {
  name                    = "gke-autopilot-vpc"
  auto_create_subnetworks = false
}

# Subnetwork with dedicated secondary IP ranges for Kubernetes Pods and Services
resource "google_compute_subnetwork" "gke_subnet" {
  name                     = "gke-autopilot-subnet"
  ip_cidr_range            = "10.10.0.0/20"
  region                   = "asia-south1"
  network                  = google_compute_network.gke_vpc.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pods"
    ip_cidr_range = "10.20.0.0/16"
  }

  secondary_ip_range {
    range_name    = "services"
    ip_cidr_range = "10.30.0.0/20"
  }
}

# GKE Autopilot Cluster in asia-south1 (Mumbai)
resource "google_container_cluster" "autopilot_cluster" {
  name             = "gke-autopilot-cluster"
  location         = "asia-south1"
  enable_autopilot = true

  network    = google_compute_network.gke_vpc.id
  subnetwork = google_compute_subnetwork.gke_subnet.id

  ip_allocation_policy {
    cluster_secondary_range_name  = google_compute_subnetwork.gke_subnet.secondary_ip_range[0].range_name
    services_secondary_range_name = google_compute_subnetwork.gke_subnet.secondary_ip_range[1].range_name
  }

  # Enforce private nodes to prevent direct exposure to the public internet
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Restrict master access to private networks by default
  master_authorized_networks_config {
    cidr_blocks {
      cidr_block   = "10.10.0.0/20"
      display_name = "subnet-internal-access"
    }
  }

  # Required organizational label for tracking
  resource_labels = {
    environment = "prod"
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Project and region can also be supplied via GOOGLE_PROJECT / GOOGLE_REGION environment variables
}

variable "project_id" {
  description = "The GCP project ID in which to create the GKE cluster."
  type        = string
}

variable "region" {
  description = "The GCP region for the regional GKE cluster and network resources."
  type        = string
  default     = "us-central1"
}

# -----------------------------------------------------------------------------
# VPC and Subnet for VPC-native, private cluster
# -----------------------------------------------------------------------------

resource "google_compute_network" "vpc" {
  name                    = "gke-vpc"
  auto_create_subnetworks = false
}

resource "google_compute_subnetwork" "subnet" {
  name                     = "gke-subnet"
  ip_cidr_range            = "10.0.0.0/20"
  region                   = var.region
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pods"
    ip_cidr_range = "10.1.0.0/16"
  }

  secondary_ip_range {
    range_name    = "services"
    ip_cidr_range = "10.2.0.0/20"
  }
}

# -----------------------------------------------------------------------------
# Least-privilege Service Account for GKE Nodes
# -----------------------------------------------------------------------------

resource "google_service_account" "gke_nodes" {
  account_id   = "gke-nodes-sa"
  display_name = "Service Account for GKE Nodes"
}

# Minimal logging and monitoring permissions for GKE nodes (no Owner/Editor)
resource "google_project_iam_member" "node_logging" {
  project = var.project_id
  role    = "roles/logging.logWriter"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

resource "google_project_iam_member" "node_monitoring" {
  project = var.project_id
  role    = "roles/monitoring.metricWriter"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

resource "google_project_iam_member" "node_monitoring_viewer" {
  project = var.project_id
  role    = "roles/monitoring.viewer"
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

# -----------------------------------------------------------------------------
# GKE Cluster (Regional, Private Nodes, Workload Identity)
# -----------------------------------------------------------------------------

resource "google_container_cluster" "primary" {
  name     = "prod-private-cluster"
  location = var.region

  network    = google_compute_network.vpc.id
  subnetwork = google_compute_subnetwork.subnet.id

  # Recommended practice: remove default node pool and manage node pools separately
  remove_default_node_pool = true
  initial_node_count       = 1

  # IP allocation policy for VPC-native routing
  ip_allocation_policy {
    cluster_secondary_range_name  = "pods"
    services_secondary_range_name = "services"
  }

  # Private nodes configuration
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
  }

  # Workload Identity configuration
  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  # Recommended release channel
  release_channel {
    channel = "REGULAR"
  }
}

# -----------------------------------------------------------------------------
# Separately Managed Node Pool
# -----------------------------------------------------------------------------

resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  cluster    = google_container_cluster.primary.id
  location   = var.region
  node_count = 2

  node_config {
    machine_type = "e2-medium"

    # Assign custom service account and recommended scopes
    service_account = google_service_account.gke_nodes.email
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    # Enforce GKE Workload Identity metadata extraction on nodes
    workload_metadata_config {
      mode = "GKE_METADATA"
    }

    labels = {
      environment = "production"
    }
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
