  }
}

provider "google" {
  region = "asia-south1"
}

variable "db_password" {
  description = "Password for the appuser SQL account"
  type        = string
  sensitive   = true
}

resource "google_sql_database_instance" "postgres" {
  name                = "app-postgres-instance"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    # Secure default: disable public IPv4 access
    ip_configuration {
      ipv4_enabled = false
    }
  }
}

# Note: The 'google_sql_database' resource documentation was not provided in the 
# retrieved context. It is declared below using standard provider conventions 
# to provision the requested 'appdb' database on the instance.
resource "google_sql_database" "appdb" {
  name     = "appdb"
  instance = google_sql_database_instance.postgres.name
}

resource "google_sql_user" "appuser" {
  name     = "appuser"
  instance = google_sql_database_instance.postgres.name
  password = var.db_password
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {}

# Custom-mode VPC network with automatically created subnetworks disabled
resource "google_compute_network" "custom_vpc" {
  name                    = "custom-vpc-network"
  auto_create_subnetworks = false
  routing_mode            = "REGIONAL"
  description             = "Custom-mode VPC network with explicit subnet management"
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Default project and region can be configured via environment variables or provider arguments
}

# VPC Network to attach the firewall rule to
resource "google_compute_network" "custom_vpc" {
  name                    = "custom-vpc"
  auto_create_subnetworks = false
}

# Firewall rule allowing inbound TCP port 22 strictly from 203.0.113.0/24
resource "google_compute_firewall" "allow_ssh_ingress" {
  name        = "allow-ssh-ingress-restricted"
  network     = google_compute_network.custom_vpc.name
  description = "Allows inbound SSH (TCP port 22) traffic only from 203.0.113.0/24"
  direction   = "INGRESS"
  priority    = 1000

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["203.0.113.0/24"]

  log_config {
    metadata = "INCLUDE_ALL_METADATA"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Dedicated service account following least-privilege practices for GKE nodes
resource "google_service_account" "node_pool_sa" {
  account_id   = "main-cluster-node-sa"
  display_name = "Service Account for main-cluster Node Pool"
}

# GKE node pool attached to the existing 'main-cluster' in asia-south1
resource "google_container_node_pool" "primary_nodes" {
  name     = "main-cluster-pool"
  cluster  = "main-cluster"
  location = "asia-south1"

  autoscaling {
    min_node_count = 1
    max_node_count = 5
  }

  management {
    auto_repair  = true
    auto_upgrade = true
  }

  node_config {
    machine_type    = "e2-medium"
    service_account = google_service_account.node_pool_sa.email

    # Google recommends custom service accounts with cloud-platform scope,
    # with access permissions controlled granularly via IAM roles.
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = {
      environment = "production"
      node-pool   = "main-cluster-pool"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Default project/credentials assumed from environment
}

# Dedicated VPC network for private workloads
resource "google_compute_network" "vpc" {
  name                    = "vpc-asia-south1"
  auto_create_subnetworks = false
  routing_mode            = "REGIONAL"
}

# Private subnetwork in asia-south1
resource "google_compute_subnetwork" "private_subnet" {
  name                     = "sb-private-asia-south1"
  ip_cidr_range            = "10.10.0.0/24"
  region                   = "asia-south1"
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true
}

# Cloud Router in asia-south1
resource "google_compute_router" "router" {
  name    = "cr-asia-south1"
  region  = "asia-south1"
  network = google_compute_network.vpc.id
}

# Cloud NAT attached to the Cloud Router for outbound internet connectivity
resource "google_compute_router_nat" "nat" {
  name                               = "nat-gateway-asia-south1"
  router                             = google_compute_router.router.name
  region                             = google_compute_router.router.region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  log_config {
    enable = true
    filter = "ERRORS_ONLY"
  }
}

