  name                        = "example-auto-delete-90-days-bucket"
  location                    = "US"
  uniform_bucket_level_access = true

  # Automatically delete objects when their age reaches 90 days
  lifecycle_rule {
    condition {
      age = 90
    }
    action {
      type = "Delete"
    }
  }

  # Clean up incomplete multipart uploads after 7 days
  lifecycle_rule {
