# Dedicated service account for the VM following the principle of least privilege
resource "google_service_account" "vm_sa" {
  account_id   = "vm-dedicated-sa"
  display_name = "Dedicated Service Account for Private VM"
  description  = "Dedicated service account used by Compute Engine VM without public IP"
}

# Compute Engine virtual machine instance without an external IP address
resource "google_compute_instance" "default" {
  name         = "private-instance"
  machine_type = "e2-medium"
  zone         = "us-central1-a"

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-11"
      labels = {
        environment = "production"
      }
    }
  }

  network_interface {
    network = "default"

    # Omitting the access_config block ensures the VM receives only
    # an internal IP address and has no public/external IP address assigned.
  }

  service_account {
    # Google recommends custom service accounts with cloud-platform scope
    # and granular permissions granted via IAM roles.
    email  = google_service_account.vm_sa.email
    scopes = ["cloud-platform"]
  }

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

