# VPC network to host the firewall rule
resource "google_compute_network" "default" {
  name                    = "custom-vpc"
  auto_create_subnetworks = false
}

# Subnet within the VPC
resource "google_compute_subnetwork" "default" {
  name          = "custom-subnet"
  ip_cidr_range = "10.0.0.0/24"
  region        = "us-central1"
  network       = google_compute_network.default.id
}

# Firewall rule allowing inbound SSH (TCP 22) only from 203.0.113.0/24
resource "google_compute_firewall" "allow_ssh_restricted" {
  name        = "allow-ssh-restricted"
  network     = google_compute_network.default.name
  description = "Allows inbound TCP port 22 traffic restricted to 203.0.113.0/24"
  direction   = "INGRESS"
  priority    = 1000

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["203.0.113.0/24"]

  log_config {
    metadata = "INCLUDE_ALL_METADATA"
  }
}

