variable "bucket_name" {
  type        = string
  description = "The globally unique name for the Cloud Storage bucket."
}

# Service Account intended for read-only access to bucket objects
resource "google_service_account" "bucket_reader" {
  project      = var.project_id
  account_id   = "storage-object-reader"
  display_name = "Storage Object Reader Service Account"
  description  = "Service account granted read-only object access to the private bucket"
}

# Private Cloud Storage bucket adhering to best practices (uniform access, no public exposure)
resource "google_storage_bucket" "private_bucket" {
  project  = var.project_id
  name     = var.bucket_name
  location = "US"

  # Enforce uniform IAM and block public access per security best practices
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  versioning {
    enabled = true
  }

  labels = {
    managed_by = "terraform"
  }
}

# Grant the service account read-only object viewer access to the bucket
resource "google_storage_bucket_iam_member" "object_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.bucket_reader.email}"
}

