# Private GKE Cluster with Workload Identity enabled
resource "google_container_cluster" "primary" {
  name     = "private-workload-id-cluster"
  location = var.region

  network    = google_compute_network.gke_network.id
  subnetwork = google_compute_subnetwork.gke_subnet.id

  # Recommended practice: remove the default node pool and manage pools separately
  remove_default_node_pool = true
  initial_node_count       = 1

  # VPC-native routing with secondary subnet ranges
  ip_allocation_policy {
    cluster_secondary_range_name  = google_compute_subnetwork.gke_subnet.secondary_ip_range[0].range_name
    services_secondary_range_name = google_compute_subnetwork.gke_subnet.secondary_ip_range[1].range_name
  }

  # Enable private nodes (nodes do not receive public IP addresses)
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Enable Workload Identity
  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  # Release channel configuration
  release_channel {
    channel = "REGULAR"
  }

  # Recommended network security configuration
  enable_shielded_nodes = true
}

