# Cloud Run v2 service configured with private access (IAM enforcement enabled by default)
resource "google_cloud_run_v2_service" "default" {
  name     = "secure-service"
  location = "us-central1"

  # Ensure invoker IAM check remains enabled (default is false, explicitly set for clarity)
  invoker_iam_disabled = false

  template {
    containers {
      image = "us-docker.pkg.dev/cloudrun/container/hello"
    }
  }
}

# Grant invoke permissions exclusively to the specified service account
resource "google_cloud_run_v2_service_iam_member" "invoker" {
  project  = google_cloud_run_v2_service.default.project
  location = google_cloud_run_v2_service.default.location
  name     = google_cloud_run_v2_service.default.name
  role     = "roles/run.invoker"
  member   = "serviceAccount:invoker-sa@my-project.iam.gserviceaccount.com"
}

