# Cloud Scheduler job running daily at 02:00 (UTC)
resource "google_cloud_scheduler_job" "daily_job" {
  name        = "daily-pubsub-trigger"
  description = "Dispatches a message to Pub/Sub daily at 02:00"
  schedule    = "0 2 * * *"
  time_zone   = "Etc/UTC"

  pubsub_target {
    topic_name = google_pubsub_topic.daily_topic.id
    data       = base64encode(jsonencode({ "event" = "daily_trigger" }))
  }
}

