# Main topic receiving messages
resource "google_pubsub_topic" "main" {
  name = "main-topic"

  labels = {
    environment = "production"
  }
}

# Dead-letter topic where failed messages are routed
resource "google_pubsub_topic" "dead_letter" {
  name = "dead-letter-topic"

  labels = {
    environment = "production"
    purpose     = "dead-letter"
  }
}

# Primary subscription configured to forward messages to the dead-letter topic
# after 5 unsuccessful delivery attempts
resource "google_pubsub_subscription" "main" {
  name  = "main-subscription"
  topic = google_pubsub_topic.main.id

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dead_letter.id
    max_delivery_attempts = 5
  }

  labels = {
    environment = "production"
  }
}

# Subscription attached to the dead-letter topic to ensure dead-lettered
# messages are retained and can be inspected or reprocessed
resource "google_pubsub_subscription" "dead_letter" {
  name  = "dead-letter-subscription"
  topic = google_pubsub_topic.dead_letter.id

  labels = {
    environment = "production"
    purpose     = "dead-letter-processing"
  }
}

