# Terraform configuration to create a Cloud KMS KeyRing and an automatically rotating symmetric CryptoKey.

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Configuration options such as project and region can be provided via environment variables
}

# KMS KeyRing to group cryptographic keys
resource "google_kms_key_ring" "keyring" {
  name     = "app-keyring"
  location = "us-central1"
}

# Symmetric CryptoKey configured to rotate every 90 days (7,776,000 seconds)
resource "google_kms_crypto_key" "symmetric_key" {
  name            = "app-symmetric-key"
  key_ring        = google_kms_key_ring.keyring.id
  purpose         = "ENCRYPT_DECRYPT"
  rotation_period = "7776000s" # 90 days = 90 * 86,400 seconds

  labels = {
    environment = "production"
  }

  lifecycle {
    # Prevent accidental destruction of cryptographic keys protecting data
    prevent_destroy = true
  }
}

