# Suffix to ensure uniqueness of the Cloud SQL instance name
resource "random_id" "db_name_suffix" {
  byte_length = 4
}

# MySQL Cloud SQL Database Instance with public IP explicitly enabled per requirement
resource "google_sql_database_instance" "mysql_public" {
  name             = "mysql-public-instance-${random_id.db_name_suffix.hex}"
  region           = "us-central1"
  database_version = "MYSQL_8_0"

  deletion_protection = true

  settings {
    tier              = "db-custom-1-3840"
    availability_type = "ZONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      # Explicitly enabled as requested for office VPN access without Cloud SQL Auth Proxy.
      # Authorized networks should be restricted to specific office public IP CIDRs
      # and must never be set to 0.0.0.0/0.
      ipv4_enabled = true
    }
  }
}

